steps.message:
Execute: adb shell "cat <<'SQL' | sqlite3 /data/user/0/com.flauschcode.broccoli/databases/broccoli
PRAGMA foreign_keys=ON;
BEGIN;
DELETE FROM recipes
WHERE recipeId IN (
  SELECT r.recipeId
  FROM recipes r
  WHERE EXISTS (
    SELECT 1
    FROM recipes r2
    WHERE r2.recipeId < r.recipeId
      AND r2.title IS r.title
      AND r2.imageName IS r.imageName
      AND r2.description IS r.description
      AND r2.servings IS r.servings
      AND r2.preparationTime IS r.preparationTime
      AND r2.source IS r.source
      AND r2.ingredients IS r.ingredients
      AND r2.directions IS r.directions
      AND r2.favorite = r.favorite
  )
);
DELETE FROM recipes_with_categories WHERE recipeId NOT IN (SELECT recipeId FROM recipes);
COMMIT;
SELECT 'remaining_duplicates', COUNT(*) FROM (
  SELECT 1
  FROM recipes
  GROUP BY title, imageName, description, servings, preparationTime, source, ingredients, directions, favorite
  HAVING COUNT(*) > 1
);
SELECT 'recipe_count', COUNT(*) FROM recipes;
SQL
am force-stop com.flauschcode.broccoli"

